import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.DYd_c05j.js";const p=JSON.parse('{"title":"Local Models","description":"","frontmatter":{},"headers":[],"relativePath":"local-models.md","filePath":"local-models.md","lastUpdated":null}'),l={name:"local-models.md"};function s(n,e,i,d,c,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="local-models" tabindex="-1">Local Models <a class="header-anchor" href="#local-models" aria-label="Permalink to &quot;Local Models&quot;">​</a></h1><p>Homelab Console is designed to make a small local model useful before asking it to be powerful. The control plane reduces the problem into compact summaries, strict tool choices, and validated outputs. Credentials, policy, task state, and write authority stay outside the model.</p><h2 id="start-with-the-smallest-model-that-works" tabindex="-1">Start with the smallest model that works <a class="header-anchor" href="#start-with-the-smallest-model-that-works" aria-label="Permalink to &quot;Start with the smallest model that works&quot;">​</a></h2><p>For read-only status questions, a local 4B model can be the best default: fast, private, inexpensive, and close to the infrastructure. The <a href="./benchmark">MCP Lite benchmark</a> measured Qwen 3.5 4B as the fastest model in all three tested summary routes while still selecting the expected tool in 3/3 tests.</p><p>That result is not a claim that a 4B model is universally better. It shows that smaller models can perform well when the control plane gives them a deliberately small problem.</p><table tabindex="0"><thead><tr><th>Workload</th><th>Suggested starting point</th><th>Why</th></tr></thead><tbody><tr><td>Deterministic summaries and status checks</td><td>Local 4B model</td><td>Lowest latency, private execution, narrow decision space</td></tr><tr><td>Richer explanations or mixed operational questions</td><td>Balanced commercial model</td><td>More headroom for synthesis without using the largest model</td></tr><tr><td>Complex diagnosis and cross-system correlation</td><td>Larger commercial model</td><td>Better fit for ambiguous evidence and longer reasoning chains</td></tr><tr><td>Infrastructure writes</td><td>Governed tool client plus operator approval</td><td>Model size never replaces validation, approval, or read-back</td></tr></tbody></table><h2 id="what-makes-local-inference-practical" tabindex="-1">What makes local inference practical <a class="header-anchor" href="#what-makes-local-inference-practical" aria-label="Permalink to &quot;What makes local inference practical&quot;">​</a></h2><p>Homelab Console does not expose a raw provider API or a large tool catalog and hope the model chooses well. It supplies:</p><ul><li>deterministic <code>lab.*.summary</code> observations;</li><li>a reduced MCP surface for the current task;</li><li>strict schemas for model decisions and tool inputs;</li><li>bounded conversation and task context;</li><li>centralized validation, redaction, and audit;</li><li>a separate human approval boundary for every infrastructure write.</li></ul><p>The model remains replaceable. The useful system knowledge lives in the control plane.</p><h2 id="current-local-paths" tabindex="-1">Current local paths <a class="header-anchor" href="#current-local-paths" aria-label="Permalink to &quot;Current local paths&quot;">​</a></h2><ul><li><strong>Ollama</strong> provides a fixed local chat endpoint for private inference.</li><li><strong>LAN AI manager</strong> uses one inventory-declared OpenAI-compatible host on the trusted network and can fall back to a configured commercial model.</li><li><strong>MCP clients</strong> can use the same governed tools from an external compatible agent without receiving provider credentials.</li></ul><p>You can run the supported Community stack with every AI runtime disabled, then connect a model after the control plane and providers are healthy.</p><h2 id="know-when-to-step-up" tabindex="-1">Know when to step up <a class="header-anchor" href="#know-when-to-step-up" aria-label="Permalink to &quot;Know when to step up&quot;">​</a></h2><p>Use a stronger model when the question requires uncertain causal reasoning, cross-provider correlation, or a remediation plan that must account for several failure modes. Keep write tools behind the same approval path regardless of the model selected.</p><p>The current benchmark covers read-only summary routing only. A separate, repeatable benchmark is required before treating a local 4B model as validated for complex diagnosis or write-oriented workflows.</p><p>For schemas, channel behavior, fallbacks, limits, and migration details, see the <a href="./conversation">Conversation Service reference</a>.</p>',17)])])}const u=t(l,[["render",s]]);export{p as __pageData,u as default};
